/* Worldseed Engine — built-in 5x7 bitmap font data (P11).
 *
 * Original glyph bitmaps authored for this engine; each glyph is seven
 * rows of five pixels, '#' = ink, '.' = empty, laid out top row first and
 * packed into one 35-character string per glyph. Index 0 is ASCII 32 (space)
 * and the table runs to ASCII 126 ('~'). This is our own font data, not a
 * copied or third-party font asset (ADR-008).
 *
 * Generated and checked so every glyph is exactly 35 characters; do not edit
 * by hand without re-checking the length. See src/ui/ws_font.c for the
 * renderer that consumes it.
 */
